class ImageFetcher(QThread):
    loaded = pyqtSignal(str, bytes)

    def __init__(self, url, filename):
        super().__init__()
        self.url = url
        self.filename = filename

    def run(self):
        try:
            r = requests.get(self.url, timeout=5)
            if r.status_code == 200:
                self.loaded.emit(self.filename, r.content)
        except:
            pass

