    std::lock_guard<std::mutex> gifLk(gifMutex);
    isStreaming = false;
    isTextMode = false;
    singleMode = true;
    currentFile = path;
    gif.close(); 

    gif.begin(LITTLE_ENDIAN_PIXELS); // Reset decoder state
    if (gif.open(path.c_str(), GIFOpenFile, GIFCloseFile, GIFReadFile, GIFSeekFile, GIFDraw)) {
        isPlaying = true;
        currentGifStartTime = millis();
        Serial.printf("Playing Single: %s (%dx%d)\n", path.c_str(), gif.getCanvasWidth(), gif.getCanvasHeight());

        dma->clearScreen();
        int tDelay = 0;
        if (gif.playFrame(false, &tDelay)) {
             if (tDelay < 1) tDelay = 1;
             nextGifFrameTime = millis() + tDelay;
        } else {
             nextGifFrameTime = millis();
        }
        pendingFileNotification = path;
    } else {
        Serial.printf("Failed to open GIF. Error: %d\n", gif.getLastError());
    }
}

